<?php
declare(strict_types=1);$root=dirname(__DIR__);$read=static fn(string $p):string=>(string)file_get_contents($root.'/'.$p);$assert=static function(bool $v,string $m):void{if(!$v)throw new RuntimeException($m);};$base=$read('app/Views/layouts/base.php');foreach(['tokens.css','themes.css','foundation.css','skip-link']as$n)$assert(str_contains($base,$n),'Base missing '.$n);$js=$read('public/assets/js/app.js');foreach(['aria-pressed','Escape','data-drawer-close']as$n)$assert(str_contains($js,$n),'Interaction missing '.$n);$portal=$read('app/Views/public/portal.php');foreach(['ThemeService::allowed','--champ-primary','--champ-secondary','--champ-accent']as$n)$assert(str_contains($portal,$n),'Public theme missing '.$n);foreach(['320px','520px','800px']as$n)$assert(str_contains($read('public/assets/css/layout.css'),$n)||str_contains($read('public/assets/css/public-portal.css'),$n),'Responsive breakpoint missing '.$n);echo "UI_UX_AUDIT_E2E_OK\n";
